"""Describe historical validation support without fitting or using outer losses."""
from pathlib import Path
import datetime,hashlib,json,statistics
O=Path(__file__).resolve().parent;source=O/'selector_fold_scaling_diagnostic.json';cases=json.loads(source.read_text())['records'];first=[r['folds'][0]for r in cases];ratios=[f['validation_horizon']/f['training_rows']for f in first]
out={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'input_diagnostic_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'cases':len(cases),'first_internal_training_rows_minimum':min(f['training_rows']for f in first),'first_internal_training_rows_median':statistics.median(f['training_rows']for f in first),'first_internal_training_rows_maximum':max(f['training_rows']for f in first),'cases_first_prefix24_or25':sum(f['training_rows']in(24,25)for f in first),'cases_first_validation_longer_than_training':sum(r>1 for r in ratios),'maximum_first_fold_horizon_to_training_rows':max(ratios),'fold_counts':{str(n):sum(len(r['folds'])==n for r in cases)for n in sorted({len(r['folds'])for r in cases})},'interpretation':'Two completed validation blocks and a legal fitting prefix are not a stability certificate. This support mismatch may influence learned weights; the diagnostic does not establish an accuracy loss, a look-ahead error or an invalid outer score. Monte Carlo replication does not resolve limited historical information.','no_outer_losses_or_scores_used':True,'no_fits_forecasts_new_workers_or_admission':True,'case_support':[{'series_id':r['series_id'],'origin_label':r['origin_label'],'known_rows':r['known_rows'],'folds':r['folds']}for r in cases]}
